import React from "react";
import { render, fireEvent, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import IconButton from "../IconButton";
import * as stories from "./Menu.stories";
import Menu, { MenuButton, MenuItem, MenuList, MenuDivider } from ".";

const { Basic } = composeStories(stories) as any;

describe("Menu component", () => {
  const callback = jest.fn();
  const menu = (
    <Menu>
      <MenuButton variant="ghost">Open</MenuButton>
      <MenuList>
        <MenuItem onClick={() => callback(1)}>Value 01</MenuItem>
        <MenuItem onClick={() => callback(2)}>Value 02</MenuItem>
        <MenuDivider />
        <MenuItem disabled onClick={() => callback(3)}>
          Value 03
        </MenuItem>
        <MenuItem onClick={() => callback(4)}>Value 04</MenuItem>
        <MenuItem disableCloseOnClick onClick={() => callback(5)}>
          Value 05
        </MenuItem>
      </MenuList>
    </Menu>
  );

  beforeEach(() => {
    jest.resetAllMocks();
  });

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    fireEvent.click(screen.getByText("Open Menu"));
    await waitFor(() => {
      expect(screen.getByRole("menu")).toBeInTheDocument();
    });
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("display menu items on click on the button", async () => {
    render(menu);
    expect(screen.queryByRole("menuitem")).toBeNull();
    fireEvent.click(screen.getByText("Open"));
    await waitFor(() => {
      expect(screen.getByRole("menu")).toBeInTheDocument();
    });
    expect(screen.getAllByRole("menuitem")).toHaveLength(5);
  });

  it("set focus back on button when closing the menu", async () => {
    render(menu);
    const button = screen.getByText("Open");
    fireEvent.click(button);
    await waitFor(() => {
      expect(screen.getByRole("menu")).toBeInTheDocument();
    });

    expect(screen.getAllByRole("menuitem")).toHaveLength(5);
    await userEvent.tab();
    expect(button).toHaveFocus();

    fireEvent.click(button);
    expect(screen.getAllByRole("menuitem")).toHaveLength(5);
    fireEvent.keyDown(screen.getByRole("menuitem", { name: "Value 01" }), {
      key: "Escape",
      code: "Escape",
    });
    expect(button).toHaveFocus();
  });

  it("handle click on enabled menu items", async () => {
    render(menu);
    fireEvent.click(screen.getByText("Open"));
    await waitFor(() => {
      expect(screen.getByRole("menu")).toBeInTheDocument();
    });

    fireEvent.click(screen.getAllByRole("menuitem")[1]);
    expect(callback).toHaveBeenCalledTimes(1);
  });

  it("blocks click on disabled menu items", async () => {
    render(menu);
    fireEvent.click(screen.getByText("Open"));
    await waitFor(() => {
      expect(screen.getByRole("menu")).toBeInTheDocument();
    });

    fireEvent.click(screen.getAllByRole("menuitem")[2]);
    expect(callback).toHaveBeenCalledTimes(0);
  });

  it("doesn't close the menu when MenuItem has disableCloseOnClick prop", async () => {
    render(menu);
    fireEvent.click(screen.getByText("Open"));
    await waitFor(() => {
      expect(screen.getByRole("menu")).toBeInTheDocument();
    });
    fireEvent.click(screen.getAllByRole("menuitem")[4]);
    expect(callback).toHaveBeenCalledTimes(1);
    expect(screen.getAllByRole("menuitem")).toHaveLength(5);
  });

  it("navigate enabled items with arrow keys", async () => {
    render(menu);
    fireEvent.click(screen.getByText("Open"));
    await waitFor(() => {
      expect(screen.getByRole("menu")).toBeInTheDocument();
    });

    const list = screen.getByRole("menu");
    const arrowDown = { key: "ArrowDown", code: "ArrowDown" };
    fireEvent.keyDown(list, arrowDown);
    fireEvent.keyDown(list, arrowDown);
    fireEvent.keyDown(list, arrowDown);
    // eslint-disable-next-line testing-library/no-node-access
    fireEvent.click(document.activeElement as Element);
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(4);
  });

  it("allow to use an IconButton", () => {
    const { container } = render(
      <Menu>
        <MenuButton variant="ghost" component={IconButton}>
          Open
        </MenuButton>
        <MenuList>
          <MenuItem>Value 01</MenuItem>
        </MenuList>
      </Menu>
    );
    expect(container).toMatchSnapshot();
  });

  it("accepts null childs #1297", () => {
    render(
      <Menu>
        <MenuButton>Open</MenuButton>
        <MenuList>
          {null}
          <MenuItem>Value 01</MenuItem>
        </MenuList>
      </Menu>
    );
  });
});
